#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>
int main(void) {
    FILE *in = fopen("temps.txt", "r");
    if (in == NULL) { printf("Cannot open temps.txt\n"); return 1; }
    int n; double t, min = 0, max = 0, sum = 0;
    fscanf(in, "%d", &n);
    for (int i = 0; i < n; i++) {
        fscanf(in, "%lf", &t);
        if (i == 0 || t < min) min = t;
        if (i == 0 || t > max) max = t;
        sum += t;
    }
    fclose(in);
    FILE *out = fopen("summary.txt", "w");
    fprintf(out, "Min: %.1f\nMax: %.1f\nMean: %.1f\n", min, max, sum / n);
    fclose(out);
    printf("Wrote summary.txt\n");
    return 0;
}

